import catalog from './catalog.json'

/**
 * Catalog of the Monster Energy range listed on monsterenergy.com/pt-br at research
 * time. Every value is transcribed from the official product page (see `sources`);
 * catalog.json is generated by tools/build-catalog.py from the saved page dumps in
 * tools/data/pages. Missing fields were not published on the pages consulted.
 */

export type LineId = 'monster-energy' | 'monster-ultra' | 'dragon-tea' | 'juice-monster'

export interface Figure {
  value: number
  unit: 'kcal' | 'mg' | 'g'
  /** Label exactly as printed on the official page. */
  officialLabel: string
}

export interface Source {
  label: string
  url: string
  accessed: string
  note?: string
}

export interface Product {
  id: string
  line: LineId
  displayName: string
  officialName: string
  /** "Sobre o sabor" statement from the official page. */
  flavor: string
  description: string
  figures: Partial<Record<'calories' | 'caffeine' | 'sugars', Figure>>
  volume: { ml: number; basis: string } | null
  ingredients: string | null
  packNotes: string[]
  image: string
  colors: { accent: string; deep: string }
  sources: Source[]
}

export interface Line {
  id: LineId
  name: string
  color: string
  description: string
  source: string
}

export const LINES = catalog.lines as Line[]
export const PRODUCTS = catalog.products as Product[]
export const CATALOG_ACCESSED = catalog.accessed
export const CATALOG_SOURCE = catalog.catalogSource

export const lineOf = (id: LineId) => LINES.find((l) => l.id === id)!
export const productById = (id: string) => PRODUCTS.find((p) => p.id === id) ?? PRODUCTS[0]

export type FigureKey = 'calories' | 'caffeine' | 'sugars'

export const FIGURE_META: Record<FigureKey, { label: string; unit: string }> = {
  calories: { label: 'Calorias', unit: 'kcal' },
  caffeine: { label: 'Cafeína', unit: 'mg' },
  sugars: { label: 'Açúcares totais', unit: 'g' },
}

/** Range of each figure across the whole catalog: the shared scale every gauge reads on. */
export const FIGURE_RANGE: Record<FigureKey, { min: number; max: number }> = (() => {
  const out = {} as Record<FigureKey, { min: number; max: number }>
  for (const k of Object.keys(FIGURE_META) as FigureKey[]) {
    const vals = PRODUCTS.map((p) => p.figures[k]?.value).filter((v): v is number => v != null)
    out[k] = { min: Math.min(...vals), max: Math.max(...vals) }
  }
  return out
})()

export const assetUrl = (path: string) => `${import.meta.env.BASE_URL}${path}`

/**
 * 600 px version of the official render (tools/compose-hd.py): Real-ESRGAN on the
 * artwork, plain Lanczos on every small-print band so no label text is altered.
 */
export const hdImage = (p: Product) => p.image.replace('products/', 'products/hd/')

/** Pre-padded JPEG for the 3D projection: HD (600 px) or the official 250 px size. */
export const textureImage = (p: Product, hd: boolean) => `products/tex/${p.id}${hd ? '' : '-sm'}.jpg`

/** srcset pairing the official 250 px render with its HD version. */
export const imageSrcSet = (p: Product) => `${assetUrl(p.image)} 250w, ${assetUrl(hdImage(p))} 600w`

export const formatNumber = (v: number) => v.toLocaleString('pt-BR', { maximumFractionDigits: 1 })
